          </CardHeader>
          <CardContent className="mt-3">
            <MaybeEmptyOverlay empty={seriesEmpty}>
              <AreaChart.EvilAreaChart
                config={volumeConfig}
                data={volumeChartData}
                isLoading={seriesLoading}
                isUpdating={!seriesEmpty && chartsStale}
