              >
                <AreaChart.Grid />
                <AreaChart.XAxis
                  dataKey="bucket"
                  ticks={seriesChartTicks}
                  tickFormatter={bucketLabel}
                  interval={0}
                  tick={edgeTick}
                />
                <AreaChart.YAxis
                  allowDecimals={false}
                  tickFormatter={(v) => formatCount(Number(v))}
                />
                <AreaChart.Tooltip
                  labelFormatter={(v) => formatBucketFull(String(v))}
                />
                <AreaChart.Area
                  dataKey="requests"
                  strokeVariant="solid"
                  enableBufferLine={seriesBuffer}
                />
                <AreaChart.Area
                  dataKey="errors"
                  strokeVariant="solid"
                  variant="lines"
                  enableBufferLine={seriesBuffer}
