type TooltipProps = {
	variant?: TooltipVariant; // visual style of the tooltip surface
	roundness?: TooltipRoundness; // border-radius of the tooltip
	defaultIndex?: number; // data index shown by default with no hover
	cursor?: boolean; // whether the vertical cursor line follows the pointer
	// Formats the tooltip's heading (the x value), e.g. a raw bucket → a date.
	labelFormatter?: ComponentProps<typeof ChartTooltipContent>["labelFormatter"];
	// Formats each row's numeric value, e.g. raw ms → "1.70s".
	valueFormatter?: ComponentProps<typeof ChartTooltipContent>["valueFormatter"];
	// Lists the rows in reverse series order (top series first).
	reverse?: ComponentProps<typeof ChartTooltipContent>["reverse"];
};

/**
 * The hover tooltip. Reads the chart's selection from context so its content
 * dims unselected series. Hidden automatically while the chart is loading.
 */
export function Tooltip({
	variant,
	roundness,
	defaultIndex,
	cursor = true,
	labelFormatter,
	valueFormatter,
	reverse,
}: TooltipProps) {
	const { isLoading, selectedDataKey, syncId, isMouseInChart } = useAreaChart();

	if (isLoading) return null;

	return (
		<ChartTooltip
			defaultIndex={defaultIndex}
			cursor={
				cursor ? { strokeDasharray: "3 3", strokeWidth: STROKE_WIDTH } : false
			}
			content={
				<ChartTooltipContent
					selected={selectedDataKey}
					roundness={roundness}
					variant={variant}
					labelFormatter={labelFormatter}
					valueFormatter={valueFormatter}
					reverse={reverse}
					// Synced peers draw the shared cursor line but stay quiet — only
					// the chart under the pointer shows tooltip content.
					hidden={syncId != null && !isMouseInChart}
				/>
			}
		/>
	);
}

type ThresholdProps = {
	value: number; // y value the line sits at, in the chart's y units
	label?: string; // small caption rendered inside the chart's right edge
